    n = int(data[0]); m = int(data[1]); s = int(data[2]) - 1; t = int(data[3]) - 1
    adj = [[] for _ in range(n)]
    idx = 4
    for _ in range(m):
        u = int(data[idx]) - 1; v = int(data[idx + 1]) - 1
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    def bfs(src):
        dist = [-1] * n
        dist[src] = 0
        dq = deque([src])
        while dq:
            x = dq.popleft()
            for y in adj[x]:
                if dist[y] < 0:
                    dist[y] = dist[x] + 1
                    dq.append(y)
        return dist

    dS = bfs(s)
    dT = bfs(t)
    d = dS[t]

    # Check whether 2d is achievable: some intermediate geodesic layer has >= 2 vertices
    cnt = [0] * (d + 1)
    for v in range(n):
        if dS[v] >= 0 and dT[v] >= 0 and dS[v] + dT[v] == d:
            cnt[dS[v]] += 1
    for i in range(1, d):
        if cnt[i] >= 2:
            print(2 * d)
            return

    # Unique geodesic path P = p[0..d]
    p = [-1] * (d + 1)
    p[d] = t
    for i in range(d, 0, -1):
        cur = p[i]
        found = -1
        for v in adj[cur]:
            if dS[v] == i - 1 and dT[v] == d - i + 1:
                found = v
                break
        p[i - 1] = found

    pos = [-1] * n
    for i in range(d + 1):
        pos[p[i]] = i

    INF = float('inf')
    best = INF

    # Pocket: an interior path vertex with an off-path neighbour gives extra cost 2
    for i in range(1, d):
        for v in adj[p[i]]:
            if pos[v] == -1:
                best = min(best, 2)
                break

    # Ears: off-path routes between p_i and p_j (i != j), extra = |R| + i - j
    lab = [[] for _ in range(n)]  # list of (value, source), distinct sources, up to 2
    heap = []
    for c in range(n):
        if pos[c] == -1:
            for v in adj[c]:
                if pos[v] >= 0:
                    heap.append((pos[v] + 1, c, pos[v]))
    heapq.heapify(heap)
    while heap:
        val, c, src = heapq.heappop(heap)
        L = lab[c]
        if len(L) >= 2:
            continue
        dup = False
        for _, s2 in L:
            if s2 == src:
                dup = True
                break
        if dup:
            continue
        L.append((val, src))
        for v in adj[c]:
            if pos[v] >= 0 and pos[v] != src:
                cand = val + 1 - pos[v]
                if cand < best:
                    best = cand
        for w in adj[c]:
            if pos[w] == -1 and len(lab[w]) < 2:
                heapq.heappush(heap, (val + 1, w, src))

    if best == INF:
        print(-1)
    else:
        print(2 * d + best)

