from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def perim(x, y):
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 2 * side + (side - x)
            return 3 * side + (side - y)

        pts = sorted(points, key=lambda p: perim(p[0], p[1]))
        n = len(pts)
        X = [p[0] for p in pts]
        Y = [p[1] for p in pts]

        def check(d):
            for s in range(n):
                cnt = 1
                idx = s
                end = s + n
                while cnt < k:
                    if end - idx - 1 < k - cnt:
                        break
                    xi = X[idx % n]
                    yi = Y[idx % n]
                    found = -1
                    for j in range(idx + 1, end):
                        jj = j if j < n else j - n
                        if abs(X[jj] - xi) + abs(Y[jj] - yi) >= d:
                            found = j
                            break
                    if found < 0:
                        break
                    idx = found
                    cnt += 1
                if cnt == k:
                    a = idx % n
                    if abs(X[a] - X[s]) + abs(Y[a] - Y[s]) >= d:
                        return True
            return False

        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

