class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        word = [None] * L

        # Place forced characters from 'T' constraints.
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    p = i + k
                    c = str2[k]
                    if word[p] is None:
                        word[p] = c
                    elif word[p] != c:
                        return ""

        forced = [w is not None for w in word]
        for p in range(L):
            if word[p] is None:
                word[p] = 'a'

        # Ensure each 'F' window differs from str2.
        for i in range(n):
            if str1[i] == 'F':
                if ''.join(word[i:i + m]) == str2:
                    j = i + m - 1
                    while j >= i and forced[j]:
                        j -= 1
                    if j < i:
                        return ""
                    word[j] = 'b'

        result = ''.join(word)

        # Final verification.
        for i in range(n):
            sub = result[i:i + m]
            if str1[i] == 'T':
                if sub != str2:
                    return ""
            else:
                if sub == str2:
                    return ""

        return result

