from collections import defaultdict


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(N: int) -> int:
            # Counts beautiful numbers in [1, N].
            # State (s, p): s = digit sum so far, p = digit product so far.
            # Unstarted (leading zeros) is encoded as s == 0, p == 1.
            if N <= 0:
                return 0
            digs = [int(c) for c in str(N)]
            free = defaultdict(int)  # non-tight prefixes (already below N)
            tight = (0, 1)           # prefix equal to N's prefix
            for d in digs:
                nf = defaultdict(int)
                for (s, p), c in free.items():
                    for x in range(10):
                        if s == 0 and x == 0:
                            key = (0, 1)
                        else:
                            key = (s + x, p * x)
                        nf[key] += c
                ts, tp = tight
                for x in range(d):
                    if ts == 0 and x == 0:
                        key = (0, 1)
                    else:
                        key = (ts + x, tp * x)
                    nf[key] += 1
                if ts == 0 and d == 0:
                    tight = (0, 1)
                else:
                    tight = (ts + d, tp * d)
                free = nf
            free[tight] += 1

            total = 0
            for (s, p), c in free.items():
                if s > 0 and p % s == 0:
                    total += c
            return total

        return count(r) - count(l - 1)
